--
-- Structure de la vue `client double`
--
DROP TABLE IF EXISTS `client double`;

CREATE ALGORITHM=UNDEFINED DEFINER=`o7708014`@`%` SQL SECURITY DEFINER VIEW `client double`  AS SELECT `c1`.`cli_id` AS `cli_id`, `c1`.`cli_id_modif` AS `cli_id_modif`, `c1`.`cli_nom` AS `cli_nom`, `c1`.`cli_emel` AS `cli_emel`, `c1`.`cli_adresse` AS `cli_adresse`, `c1`.`cli_adresse1` AS `cli_adresse1`, `c1`.`cli_code_postal` AS `cli_code_postal`, `c1`.`cli_ville` AS `cli_ville`, `c1`.`cli_telephone` AS `cli_telephone`, `c1`.`cli_telephone_bis` AS `cli_telephone_bis`, `c1`.`cli_taux_com` AS `cli_taux_com`, `c1`.`cli_prix_depot` AS `cli_prix_depot` FROM `bav_client` AS `c1` WHERE `c1`.`cli_nom` in (select `c2`.`cli_nom` from `bav_client` `c2` where (((`c1`.`cli_telephone` = `c2`.`cli_telephone`) OR (`c1`.`cli_telephone_bis` = `c2`.`cli_telephone_bis`) OR (`c1`.`cli_nom` = `c2`.`cli_nom`)) AND (`c1`.`cli_id` <> `c2`.`cli_id`)))) ;

-- --------------------------------------------------------

--
-- Structure de la vue `v_marque`
--
DROP TABLE IF EXISTS `v_marque`;

CREATE ALGORITHM=UNDEFINED DEFINER=`o7708014`@`%` SQL SECURITY DEFINER VIEW `v_marque`  AS SELECT DISTINCT `bo`.`obj_marque` AS `obj_marque`, `bo`.`obj_numero_bav` AS `obj_numero_bav` FROM `bav_objet` AS `bo``bo` ;

