(668, 1, '2011-05-17 21:39:08', '2011-05-17 19:39:08', '', '2011 05 15 Allaire 06', '', 'inherit', 'open', 'open', '', '2011-05-15-allaire-06', '', '', '2011-05-17 21:39:08', '2011-05-17 19:39:08', '', 666, 'http://avs44.com/wordpress/wp-content/uploads/2011/05/2011-05-15-Allaire-06.jpg', 0, 'attachment', 'image/jpeg', 0),
